// === Tab: Sketch ===
// By Roni Kaufman
// inspired by https://twitter.com/dmitricherniak/status/1214888292421951488?s=09

let particles = [];
let circles = [];
let squiggliness = 1/200;
let interval;
let margin = 10;
let theEnd = false;
let r = 200;
let noiseFactor;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 100);
  noStroke();

  background(0);
	generateCircles();
  updateParticles();

	squiggliness = 1/random(100, 200);
	noiseFactor = random(50, 100);

  interval = setInterval(updateParticles, 10000);
}

function draw() {
	if (theEnd) {
		// noLoop() removed for animation
	} else {
		for (let p of particles) {
			p.draw();
			p.move();
		}
	}
	//fill(0);
	//circle(width/2, height/2, r);
}

function updateParticles() {
  particles = [];
	let xCenter = width/2;
	let yCenter = height/2;
	let n = r*10;
  for (let i = 0; i < n; i++) {
		let theta = map(i, 0, n, -PI, PI);
    let x_ = xCenter + r*cos(theta);
    let y_ = yCenter + r*sin(theta);
		let s_ = 1;
    particles.push(new Particle(x_, y_, s_));
  }
	r -= 20;
	if (r < 20) {
		clearInterval(interval);
		theEnd = true;
	}
}

function Particle(x_, y_, s_) {
  this.x = x_;
  this.y = y_;
  this.size = s_;

  this.alpha = 100;
  this.dist = 1;

  this.move = function() {
    var theta = noise(this.x * squiggliness, this.y * squiggliness, r/1000)*PI*noiseFactor;
    let v = p5.Vector.fromAngle(theta, this.dist);
    this.x += v.x;
    this.y += v.y;
    //this.dist *= 0.999;
    this.alpha *= 0.99;
		this.size *= 0.99;
  }

  this.draw = function() {
		let d = distanceToCircles(this.x, this.y)*100;
		fill((d*10)%100, 20, 100);
    circle(this.x, this.y, this.size);
  }
}

function generateCircles() {
	//fill(100);
	let maxCircles = 20;
	var xCenter = width/2;
	var yCenter = height/2;
	for (let i = 0; i < maxCircles; i++) {
		var x_ = xCenter + random(-r, r);
		var y_ = yCenter + random(-r, r);
		let r_ = random(20, 70);
		if (!intersectsWithOtherCircles(x_, y_, r_)) {
			circles.push({x: x_, y: y_, r: r_});
			//circle(x_, y_, r_*2);
		}
	}
}

function intersectsWithOtherCircles(x_, y_, r_) {
	for (let c of circles) {
		if (dist(c.x, c.y, x_, y_) < c.r + r_ + margin) {
			return true;
		}
	}
	return false;
}

function distanceToCircles(x_, y_) {
	var d = 0;
	for (let c of circles) {
		d += c.r/dist(c.x, c.y, x_, y_)
	}
	return d;
}
